-- SymPy Pipeline: add enrichment fields + expand pool vocabulary
-- coreConcept and distractorRationale generated by Haiku during narration (no separate enrich step)
-- pool values: diagnostic | drill | test | reference

ALTER TABLE sympy_questions
    ADD COLUMN core_concept         TEXT,
    ADD COLUMN distractor_rationale JSONB;

-- Widen pool column to accommodate all pool values (diagnostic is 10 chars, fine)
-- Expand status to support 'promoted' (question copied to production questions table)
ALTER TABLE sympy_questions
    ALTER COLUMN pool   TYPE VARCHAR(20),
    ALTER COLUMN status TYPE VARCHAR(30);

-- Index for pool-based filtering (e.g. fetch all diagnostic questions)
CREATE INDEX idx_sympy_pool ON sympy_questions(pool);
